//! `lunepack publish push`: the real binary over `--store-dir` and over the signature-checking fake
//! S3 server. Keys are generated by the binary at test time; the store credentials are made up at
//! test time too. The order, failure-injection, race and mutation tests drive the push logic
//! directly (unit tests in `src/cmd_publish/push.rs`).

mod common;

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Output;
use std::sync::Arc;
use std::time::{SystemTime, UNIX_EPOCH};

use common::*;
use lunepack_testkit::{FakeS3Config, FakeS3Server};

const APP: &str = "org.example.hello";
const P: &str = "hello";

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

fn target() -> &'static str {
    if cfg!(windows) {
        "windows-x86_64"
    } else {
        "linux-x86_64"
    }
}

fn now() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_secs()
}

/// A text that differs per run and per call, for made-up credentials.
fn made_up(tag: &str, len: usize) -> String {
    let seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    let mut out = String::from(tag);
    let mut x = seed ^ (std::process::id() as u128) << 64;
    while out.len() < len {
        x = x
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        out.push(char::from(
            b"ABCDEFGHJKLMNPQRSTUVWXYZ23456789"[(x >> 59) as usize % 32],
        ));
    }
    out
}

/// Every file under `dir` with its bytes, by relative path.
fn tree(dir: &Path) -> BTreeMap<String, Vec<u8>> {
    fn walk(base: &Path, at: &Path, out: &mut BTreeMap<String, Vec<u8>>) {
        let Ok(listing) = fs::read_dir(at) else {
            return;
        };
        for entry in listing {
            let path = entry.unwrap().path();
            if path.is_dir() {
                walk(base, &path, out);
            } else {
                let rel = path
                    .strip_prefix(base)
                    .unwrap()
                    .to_string_lossy()
                    .replace('\\', "/");
                out.insert(rel, fs::read(&path).unwrap());
            }
        }
    }
    let mut out = BTreeMap::new();
    walk(dir, dir, &mut out);
    out
}

struct Fixture {
    dir: tempfile::TempDir,
    pack_config: PathBuf,
    release_signer: PathBuf,
    epoch: String,
    secrets: Vec<Vec<u8>>,
}

impl Fixture {
    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut env = env.to_vec();
        env.push(("SOURCE_DATE_EPOCH", &self.epoch));
        let out = run(args, &env);
        let secrets: Vec<&[u8]> = self.secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&out, &secrets);
        out
    }

    fn generate(&mut self, name: &str) -> (PathBuf, String) {
        let base = self.dir.path().join(name);
        let out = self.run(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        self.secrets.push(fs::read(&path).unwrap());
        (path, field(&stdout(&out), "public:"))
    }

    /// Keys, the config `pack` runs under, `keys.json` and the publisher's state file, with every
    /// document issued at `epoch`.
    fn new(epoch: u64) -> (Fixture, PathBuf) {
        let mut f = Fixture {
            pack_config: PathBuf::new(),
            release_signer: PathBuf::new(),
            epoch: epoch.to_string(),
            secrets: Vec::new(),
            dir: tempfile::tempdir().unwrap(),
        };
        let (root, root_public) = f.generate("root");
        let (release, release_public) = f.generate("release");
        f.release_signer = release;
        f.pack_config = f.dir.path().join("lunepack.toml");
        let out = f.run(
            &[
                "--config",
                s(&f.pack_config),
                "init",
                "--app-id",
                APP,
                "--root-key",
                &root_public,
            ],
            &[],
        );
        assert_ok(&out, "init");
        let origin = f.dir.path().join("origin");
        fs::create_dir(&origin).unwrap();
        let root_sign = format!("file:{}", s(&root));
        let out = f.run(
            &[
                "--config",
                s(&f.pack_config),
                "keys",
                "set",
                "--release-dir",
                s(&origin),
                "--threshold",
                "1",
                "--release-key",
                &release_public,
                "--sign",
                &root_sign,
            ],
            &[],
        );
        assert_ok(&out, "keys set");
        (f, origin)
    }

    /// The app's config: the root, `[update]`, `[install]` and `[publish]` with `store`.
    fn config(&self, store: &str) -> PathBuf {
        let mut text = fs::read_to_string(&self.pack_config).unwrap();
        text.push_str(&format!(
            "\n[update]\nfeed = \"https://updates.example.com/hello/\"\n\n[install]\nentry = \"bin/app\"\nname = \"Hello\"\n\n\
             [publish]\nprefix = \"{P}\"\n{store}\naccess_key_env = \"HELLO_STORE_KEY\"\nsecret_key_env = \"HELLO_STORE_SECRET\"\n\
             public_bucket = \"hello-public\"\nprivate_bucket = \"hello-private\"\nkeep = 1\n"
        ));
        let path = self.dir.path().join(format!("app-{}.toml", text.len()));
        fs::write(&path, text).unwrap();
        path
    }

    fn r2_config(&self) -> PathBuf {
        self.config("store = \"r2\"\naccount_id_env = \"HELLO_R2_ACCOUNT_ID\"")
    }

    fn state(&self) -> Vec<u8> {
        fs::read(self.dir.path().join("lunepack-state.json")).unwrap()
    }

    /// A `--store-dir` with `keys.json` and the state file, as `publish init` leaves them.
    fn store_dir(&self, origin: &Path) -> PathBuf {
        let store = self.dir.path().join("store");
        let public = store.join("public").join(P);
        let private = store.join("private").join(P);
        fs::create_dir_all(&public).unwrap();
        fs::create_dir_all(&private).unwrap();
        fs::copy(origin.join("keys.json"), public.join("keys.json")).unwrap();
        fs::write(private.join("lunepack-state.json"), self.state()).unwrap();
        store
    }

    /// A release directory with the public bucket's documents (what `fetch` would write), with
    /// `version` packed into it.
    fn release_dir(
        &self,
        name: &str,
        public: &BTreeMap<String, Vec<u8>>,
        version: &str,
    ) -> PathBuf {
        let rd = self.dir.path().join(name);
        for (rel, bytes) in public {
            let path = rd.join(rel);
            fs::create_dir_all(path.parent().unwrap()).unwrap();
            fs::write(path, bytes).unwrap();
        }
        fs::create_dir_all(&rd).unwrap();
        let input = self.dir.path().join(format!("input-{version}"));
        fs::create_dir_all(input.join("bin")).unwrap();
        fs::write(
            input.join("bin/app"),
            format!("app {version}\n").repeat(300),
        )
        .unwrap();
        let sign = format!("file:{}", s(&self.release_signer));
        let out = self.run(
            &[
                "--config",
                s(&self.pack_config),
                "pack",
                "--input",
                s(&input),
                "--version",
                version,
                "--target",
                target(),
                "--release-dir",
                s(&rd),
                "--sign",
                &sign,
            ],
            &[],
        );
        assert_ok(&out, "pack");
        rd
    }

    fn push(
        &self,
        config: &Path,
        rd: &Path,
        version: &str,
        extra: &[&str],
        env: &[(&str, &str)],
    ) -> Output {
        let sign = format!("file:{}", s(&self.release_signer));
        let mut args = vec![
            "--config",
            s(config),
            "publish",
            "push",
            "--release-dir",
            s(rd),
            "--version",
            version,
            "--sign",
            &sign,
        ];
        args.extend_from_slice(extra);
        self.run(&args, env)
    }
}

fn public_of(store: &Path) -> BTreeMap<String, Vec<u8>> {
    tree(&store.join("public").join(P))
}

#[test]
fn the_secret_scan_catches_what_it_claims_to() {
    self_check_secret_scan();
}

#[test]
fn a_push_to_a_store_dir_publishes_and_a_dry_run_writes_nothing() {
    let (f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();
    let store = f.store_dir(&origin);
    let rd = f.release_dir("rd-1", &public_of(&store), "1.0.0");
    let store_arg = s(&store).to_owned();

    let before = tree(&store);
    let out = f.push(
        &config,
        &rd,
        "1.0.0",
        &["--store-dir", &store_arg, "--dry-run"],
        &[],
    );
    assert_ok(&out, "dry run");
    let text = stdout(&out);
    assert!(
        text.contains(&format!("would upload: {P}/1.0.0/{}.pack", target())),
        "{text}"
    );
    assert!(
        text.contains(&format!("would write: {P}/feed-stable.json")),
        "{text}"
    );
    assert!(text.contains("dry run: nothing was written"), "{text}");
    assert!(tree(&store) == before, "a dry run changed the store");

    let out = f.push(&config, &rd, "1.0.0", &["--store-dir", &store_arg], &[]);
    assert_ok(&out, "push");
    let public = public_of(&store);
    assert!(
        public.contains_key("feed-stable.json"),
        "{:?}",
        public.keys()
    );
    assert!(public.contains_key(&format!("1.0.0/{}.manifest.json", target())));
    let private = tree(&store.join("private").join(P));
    assert!(
        private["lunepack-state.json"] != f.state(),
        "the state file was not written"
    );
    assert_eq!(
        private["lunepack-pending-deletes.json"],
        b"{\"format\":1,\"keys\":[],\"uploading\":[]}\n"
    );

    // The next release, with keep = 1: 1.0.0 is dropped and purged.
    let rd = f.release_dir("rd-2", &public, "1.1.0");
    let out = f.push(&config, &rd, "1.1.0", &["--store-dir", &store_arg], &[]);
    assert_ok(&out, "second push");
    let text = stdout(&out);
    assert!(
        text.contains(&format!("deleted: {P}/1.0.0/{}.pack", target())),
        "{text}"
    );
    let public = public_of(&store);
    assert!(
        !public.keys().any(|k| k.starts_with("1.0.0/")),
        "{:?}",
        public.keys()
    );
    // A rerun of a finished push changes nothing.
    let before = tree(&store);
    let out = f.push(&config, &rd, "1.1.0", &["--store-dir", &store_arg], &[]);
    assert_ok(&out, "rerun");
    assert!(
        tree(&store) == before,
        "a rerun of a finished push changed the store"
    );
}

#[test]
fn missing_credentials_are_named_and_never_shown() {
    let (mut f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();
    let store = f.store_dir(&origin);
    let rd = f.release_dir("rd", &public_of(&store), "1.0.0");
    let key = made_up("KEY", 20);
    let secret = made_up("SECRET", 40);
    f.secrets.push(key.clone().into_bytes());
    f.secrets.push(secret.clone().into_bytes());
    for (env, named) in [
        (vec![], "HELLO_STORE_KEY"),
        (
            vec![("HELLO_STORE_KEY", key.as_str())],
            "HELLO_STORE_SECRET",
        ),
        (
            vec![
                ("HELLO_STORE_KEY", key.as_str()),
                ("HELLO_STORE_SECRET", secret.as_str()),
            ],
            "HELLO_R2_ACCOUNT_ID",
        ),
        (
            vec![
                ("HELLO_STORE_KEY", ""),
                ("HELLO_STORE_SECRET", secret.as_str()),
                ("HELLO_R2_ACCOUNT_ID", "0123456789abcdef0123456789abcdef"),
            ],
            "HELLO_STORE_KEY",
        ),
    ] {
        let out = f.push(&config, &rd, "1.0.0", &[], &env);
        let err = assert_fails(&out, 1, named);
        assert!(
            err.contains(&format!("the environment variable {named}")),
            "{err}"
        );
        assert!(
            stdout(&out).is_empty(),
            "something was read: {}",
            stdout(&out)
        );
    }
    // An account id that is not one is refused before any request, without echoing it.
    let out = f.push(
        &config,
        &rd,
        "1.0.0",
        &[],
        &[
            ("HELLO_STORE_KEY", key.as_str()),
            ("HELLO_STORE_SECRET", secret.as_str()),
            ("HELLO_R2_ACCOUNT_ID", "not-an-account"),
        ],
    );
    let err = assert_fails(&out, 1, "bad account id");
    assert!(
        err.contains("account id") && !err.contains("not-an-account"),
        "{err}"
    );
    assert!(stdout(&out).is_empty());
    // --store-dir reads no variable at all.
    let out = f.push(
        &config,
        &rd,
        "1.0.0",
        &["--store-dir", s(&store), "--dry-run"],
        &[],
    );
    assert_ok(&out, "store dir without credentials");
}

#[test]
fn usage_errors_exit_2_and_refusals_exit_1() {
    let (f, origin) = Fixture::new(now() - 3600);
    let config = f.r2_config();
    let store = f.store_dir(&origin);
    let rd = f.release_dir("rd", &public_of(&store), "1.0.0");
    let store_arg = s(&store).to_owned();
    for (version, extra) in [
        ("1.0", vec![]),
        ("../1.0.0", vec![]),
        ("1.0.0", vec!["--require-targets", "not-a-target"]),
    ] {
        let mut args = vec!["--store-dir", store_arg.as_str()];
        args.extend(extra);
        let out = f.push(&config, &rd, version, &args, &[]);
        assert_fails(&out, 2, version);
    }
    let out = run(
        &[
            "--config",
            s(&config),
            "publish",
            "push",
            "--release-dir",
            s(&rd),
            "--version",
            "1.0.0",
        ],
        &[],
    );
    assert_fails(&out, 2, "no --sign");

    // A required target the release does not have.
    let out = f.push(
        &config,
        &rd,
        "1.0.0",
        &[
            "--store-dir",
            &store_arg,
            "--require-targets",
            "macos-aarch64",
        ],
        &[],
    );
    let err = assert_fails(&out, 1, "required target");
    assert!(err.contains("no macos-aarch64 target"), "{err}");

    // The release dir was not built against the store's documents.
    let mut keys = fs::read(rd.join("keys.json")).unwrap();
    keys.push(b'\n');
    fs::write(rd.join("keys.json"), keys).unwrap();
    let before = tree(&store);
    let out = f.push(&config, &rd, "1.0.0", &["--store-dir", &store_arg], &[]);
    let err = assert_fails(&out, 1, "changed since fetch");
    assert!(
        err.contains("the store changed since fetch: keys.json"),
        "{err}"
    );
    assert!(tree(&store) == before);

    // No state file in the store.
    fs::remove_file(store.join("private").join(P).join("lunepack-state.json")).unwrap();
    let out = f.push(&config, &rd, "1.0.0", &["--store-dir", &store_arg], &[]);
    let err = assert_fails(&out, 1, "no state");
    assert!(err.contains("publish init"), "{err}");
}

#[test]
fn a_push_to_s3_signs_at_the_system_clock_with_an_old_source_date_epoch() {
    // Every document is issued two hours ago; the fake refuses a request time more than 15
    // minutes from its own (system) clock, so the signing time must not be SOURCE_DATE_EPOCH.
    let (mut f, origin) = Fixture::new(now() - 7200);
    let access = made_up("AKID", 20);
    let secret = made_up("S", 40);
    f.secrets.push(access.clone().into_bytes());
    f.secrets.push(secret.clone().into_bytes());
    let server = FakeS3Server::start(FakeS3Config::new(
        &["hello-public", "hello-private"],
        "us-east-1",
        &access,
        &secret,
        Arc::new(lunepack::SystemClock),
    ))
    .unwrap();
    server.seed(
        "hello-public",
        "hello/keys.json",
        &fs::read(origin.join("keys.json")).unwrap(),
    );
    server.seed("hello-private", "hello/lunepack-state.json", &f.state());
    let config =
        f.config("store = \"s3\"\nendpoint_env = \"HELLO_S3_ENDPOINT\"\nregion = \"us-east-1\"");
    let public: BTreeMap<String, Vec<u8>> = [(
        "keys.json".to_owned(),
        fs::read(origin.join("keys.json")).unwrap(),
    )]
    .into();
    let rd = f.release_dir("rd", &public, "1.0.0");
    let endpoint = server.endpoint();
    let env = [
        ("HELLO_S3_ENDPOINT", endpoint.as_str()),
        ("HELLO_STORE_KEY", access.as_str()),
        ("HELLO_STORE_SECRET", secret.as_str()),
    ];
    let out = f.push(&config, &rd, "1.0.0", &[], &env);
    assert_ok(&out, "push to the fake S3");
    assert!(
        server
            .object("hello-public", "hello/feed-stable.json")
            .is_some()
    );
    assert!(
        server
            .object("hello-public", &format!("hello/1.0.0/{}.pack", target()))
            .is_some()
    );
    assert_eq!(
        server
            .content_type("hello-public", "hello/feed-stable.json")
            .as_deref(),
        Some("application/json")
    );
    assert!(
        server
            .object("hello-private", "hello/lunepack-state.json")
            .unwrap()
            != f.state()
    );
    assert!(
        server.requests().iter().all(|r| r.status != 403),
        "a request was refused"
    );
    // Nothing printed holds a header, a query string or the endpoint's address.
    for text in [stdout(&out), stderr(&out)] {
        let lower = text.to_lowercase();
        for needle in ["authorization", "x-amz-", "signature", "?", "127.0.0.1"] {
            assert!(!lower.contains(needle), "the output holds {needle:?}");
        }
    }
    // A wrong secret is a refusal naming the key and the status only.
    let wrong = made_up("W", 40);
    f.secrets.push(wrong.clone().into_bytes());
    let out = f.push(
        &config,
        &rd,
        "1.0.0",
        &[],
        &[
            ("HELLO_S3_ENDPOINT", endpoint.as_str()),
            ("HELLO_STORE_KEY", access.as_str()),
            ("HELLO_STORE_SECRET", wrong.as_str()),
        ],
    );
    let err = assert_fails(&out, 1, "wrong secret");
    assert!(
        err.contains("hello/lunepack-state.json answered status 403"),
        "{err}"
    );
}
